/**
 * Emoji artwork for quote stickers.
 *
 * The text atlas is ASCII-only and the isolate has no font engine, so emoji are
 * decoded from a baked atlas (emoji_atlas.js, generated by
 * scripts/build_emoji_atlas.js from Google Noto Emoji, Apache-2.0).
 *
 * The set is curated — 258 emoji covering faces, hearts, animals, flowers,
 * food, travel, objects and symbols. Anything outside it is reported as
 * unsupported rather than drawn as a wrong picture.
 *
 * Two jobs:
 *   1. the avatar disc: a name that is just an emoji (🕸️) uses that emoji as its
 *      profile picture instead of a blank lettered disc
 *   2. the name itself, once the caller has decided to draw emoji inline
 */

import { zlibInflate } from './inflate.js';
import { base64Decode } from './text.js';
import {
  EMOJI_CODEPOINTS, EMOJI_COLUMNS, EMOJI_DEFLATED_BASE64, EMOJI_EM,
  EMOJI_HEIGHT, EMOJI_WIDTH,
} from './emoji_atlas.js';

let atlas = null;
let index = null;

/** Inflate the atlas and build the codepoint → tile index once per isolate. */
export function loadEmojiAtlas() {
  if (!atlas) {
    const bytes = zlibInflate(base64Decode(EMOJI_DEFLATED_BASE64));
    if (bytes.length !== EMOJI_WIDTH * EMOJI_HEIGHT * 4) {
      throw new Error(`emoji atlas corrupt: ${bytes.length} bytes, expected ${EMOJI_WIDTH * EMOJI_HEIGHT * 4}`);
    }
    atlas = bytes;
    index = new Map();
    EMOJI_CODEPOINTS.forEach((hex, i) => {
      const cp = parseInt(hex, 16);
      if (!index.has(cp)) index.set(cp, i);
    });
  }
  return atlas;
}

/** Is this code point in the baked set? */
export function hasEmoji(cp) {
  loadEmojiAtlas();
  return index.has(cp);
}

/** Size of the atlas, for tests and diagnostics. */
export function emojiCount() {
  loadEmojiAtlas();
  return index.size;
}

/**
 * The first emoji in `text` that the atlas can draw, or 0.
 *
 * Variation selectors (U+FE0F) and zero-width joiners are skipped, so "🕸️"
 * resolves on the spider web rather than on the invisible selector.
 */
export function firstEmojiOf(text) {
  loadEmojiAtlas();
  for (const ch of String(text ?? '')) {
    const cp = ch.codePointAt(0);
    if (index.has(cp)) return cp;
  }
  return 0;
}

/** Bilinear sample of one channel from the atlas, at tile-space (u, v). */
function sample(tile, u, v, channel) {
  const col = tile % EMOJI_COLUMNS;
  const row = Math.floor(tile / EMOJI_COLUMNS);
  const baseX = col * EMOJI_EM;
  const baseY = row * EMOJI_EM;

  const x = Math.min(EMOJI_EM - 1, Math.max(0, u));
  const y = Math.min(EMOJI_EM - 1, Math.max(0, v));
  const x0 = Math.floor(x);
  const y0 = Math.floor(y);
  const x1 = Math.min(EMOJI_EM - 1, x0 + 1);
  const y1 = Math.min(EMOJI_EM - 1, y0 + 1);
  const fx = x - x0;
  const fy = y - y0;

  const at = (px, py) => atlas[((baseY + py) * EMOJI_WIDTH + baseX + px) * 4 + channel];
  const top = at(x0, y0) * (1 - fx) + at(x1, y0) * fx;
  const bottom = at(x0, y1) * (1 - fx) + at(x1, y1) * fx;
  return top * (1 - fy) + bottom * fy;
}

/**
 * Draw an emoji into a circular area, replacing what is underneath it.
 *
 * Sampling is bilinear: the atlas stores 32 px emoji and the avatar disc is
 * 124 px across, so nearest-neighbour would look blocky.
 *
 * @param {object} surface  a render.Surface
 * @param {number} codepoint
 * @param {number} cx  centre x
 * @param {number} cy  centre y
 * @param {number} radius
 * @param {number} [fill]  how much of the radius the artwork covers (default 0.92)
 * @returns {boolean} false when the code point is not in the atlas
 */
export function drawEmoji(surface, codepoint, cx, cy, radius, fill = 0.92) {
  loadEmojiAtlas();
  const tile = index.get(codepoint);
  if (tile === undefined) return false;

  const span = radius * fill * 2; // artwork width in device pixels
  for (let py = Math.floor(cy - radius) - 1; py <= Math.ceil(cy + radius) + 1; py += 1) {
    for (let px = Math.floor(cx - radius) - 1; px <= Math.ceil(cx + radius) + 1; px += 1) {
      const dx = px + 0.5 - cx;
      const dy = py + 0.5 - cy;
      const distance = Math.sqrt(dx * dx + dy * dy) - radius;
      const coverage = Math.min(1, Math.max(0, 0.5 - distance));
      if (coverage <= 0) continue;

      // Map the device pixel into the emoji tile.
      const u = ((px + 0.5 - cx) / span + 0.5) * EMOJI_EM;
      const v = ((py + 0.5 - cy) / span + 0.5) * EMOJI_EM;
      if (u < 0 || v < 0 || u >= EMOJI_EM || v >= EMOJI_EM) continue;

      const alpha = sample(tile, u, v, 3);
      if (alpha <= 0) continue;
      surface.blend(
        px, py,
        Math.round(sample(tile, u, v, 0)),
        Math.round(sample(tile, u, v, 1)),
        Math.round(sample(tile, u, v, 2)),
        coverage * (alpha / 255),
      );
    }
  }
  return true;
}

/**
 * Mean luminance of an emoji's visible pixels (0–255).
 *
 * Used to pick a disc that the artwork actually reads against: the Noto spider
 * web is dark grey, so putting it on the dark fallback disc makes it vanish.
 */
export function emojiLuminance(codepoint) {
  loadEmojiAtlas();
  const tile = index.get(codepoint);
  if (tile === undefined) return 128;

  const col = tile % EMOJI_COLUMNS;
  const row = Math.floor(tile / EMOJI_COLUMNS);
  const baseX = col * EMOJI_EM;
  const baseY = row * EMOJI_EM;

  let sum = 0;
  let weight = 0;
  for (let y = 0; y < EMOJI_EM; y += 1) {
    for (let x = 0; x < EMOJI_EM; x += 1) {
      const i = ((baseY + y) * EMOJI_WIDTH + baseX + x) * 4;
      const alpha = atlas[i + 3] / 255;
      if (alpha <= 0.05) continue;
      sum += (0.299 * atlas[i] + 0.587 * atlas[i + 1] + 0.114 * atlas[i + 2]) * alpha;
      weight += alpha;
    }
  }
  return weight ? sum / weight : 128;
}
